// Faith Forward K9 Handler Training Suite curriculum.
// Programs run in order. The Protection program is gated behind obedience,
// temperament evaluation, veterinary clearance and a certified helper.

export type BreedKey = 'pit' | 'gsd' | 'mal' | 'lab';

export interface Lesson {
  id: string;
  title: string;
  objective: string;
  equipment: string[];
  sessionMin: string;
  steps: string[];
  criteria: string;
  problems: { issue: string; fix: string }[];
  safety?: string[];
  breedTips?: Partial<Record<BreedKey, string>>;
  reflection?: string;
}

export interface Program {
  id: string;
  name: string;
  level: string;
  description: string;
  gate?: string[];
  lessons: Lesson[];
}

export const breedKey = (breedId: string): BreedKey =>
  breedId.startsWith('pitbull') ? 'pit' : breedId === 'gsd' ? 'gsd' : breedId === 'malinois' ? 'mal' : 'lab';

const STD_REWARDS = ['6-ft flat leash', 'Flat collar or harness', 'Treat pouch with pea-size high-value treats', 'Tug toy'];

